def test_different_event_prev_hash(self):
    _i, left_base = self.row("t", 1, event={"v": 1})
    for field in ("event", "prev", "hash"):
        if field == "event":
            _i, right = self.row("t", 1, event={"v": 2})
        elif field == "prev":
            _i, right = self.row("t", 1, prev="9" * 64,
                                 hash_=AuditChain._hash({
                                     "tenant": "t", "seq": 1,
                                     "event": {}, "prev": "9" * 64}))
        else:
            _i, right = self.row(
                "t", 1,
                hash_=AuditChain._hash({
                    "tenant": "t", "seq": 1, "event": {"other": True},
                    "prev": ZERO}))
        r = self.other.compare_bytes(left_base, right)
        self.assertEqual((r["equal"], r["tenant"], r["seq"],
                          r["reason"]),
                         (False, "t", 1, "different"), field)
        self.assertIsNotNone(r["left"])
        self.assertIsNotNone(r["right"])

